'use strict';

const input = $input.first()?.json || {};
const row = input.stateOutbox && typeof input.stateOutbox === 'object' ? input.stateOutbox : input;
const text = value => String(value ?? '').normalize('NFKC').trim();
const list = value => Array.isArray(value) ? value : [];
const object = value => value && typeof value === 'object' && !Array.isArray(value) ? value : {};
const jsonObject = value => {
  if (value && typeof value === 'object' && !Array.isArray(value)) return value;
  if (typeof value !== 'string' || !value.trim()) return {};
  try { return object(JSON.parse(value)); } catch { return {}; }
};

const payload = jsonObject(row.payloadJson ?? row.payload_json);
const appliedResult = object(payload.appliedResult);
const summaryPayload = object(payload.summary);
const sourceType = text(row.sourceType || row.source_type || 'analysis').toLowerCase();
const allowedSourceTypes = new Set(['analysis', 'clarification', 'principal_context', 'state_summary']);
if (!allowedSourceTypes.has(sourceType)) throw new Error(`State Qdrant outbox: unsupported source type ${sourceType || '(empty)'}.`);

const principalId = text(payload.principalId || appliedResult.principalId || summaryPayload.principalId || row.principalId || row.principal_id);
const collection = text(payload.qdrantCollection || appliedResult.qdrantCollection || summaryPayload.qdrantCollection || row.qdrantCollection || row.qdrant_collection);
const tenantId = text(payload.memoryTenantId || appliedResult.memoryTenantId || summaryPayload.memoryTenantId || row.memoryTenantId || row.memory_tenant_id);
const pointId = text(row.qdrantPointId || row.qdrant_point_id || payload.qdrantPointId);
const sourceKey = text(row.sourceKey || row.source_key || row.dedupeKey || row.dedupe_key || payload.inputId || payload.clarificationId || payload.evaluationId);
const outboxId = text(row.outboxId || row.outbox_id || row.id);
if (!principalId || !collection || !tenantId || !pointId || !sourceKey) {
  throw new Error('State Qdrant outbox: identity, source, collection, tenant, or point context is incomplete.');
}

const sphereNames = {
  health: 'Здоровье', energy: 'Энергия', mood: 'Настроение', calm: 'Спокойствие', clarity: 'Ясность',
  motivation: 'Мотивация', relationships: 'Отношения', progress: 'Прогресс', inspiration: 'Вдохновлённость', finance: 'Финансы'
};
const stateValues = list(payload.state).length ? list(payload.state)
  : list(appliedResult.state).length ? list(appliedResult.state)
    : list(summaryPayload.state);
const stateLines = stateValues.map(value => {
  const code = text(value.sphereCode);
  const score = Number(value.effectiveScore ?? value.score);
  const confidence = Number(value.confidence ?? value.modelConfidence);
  if (!code || !Number.isFinite(score)) return '';
  return `${sphereNames[code] || code}: ${score}${Number.isFinite(confidence) ? ` (уверенность ${confidence})` : ''}`;
}).filter(Boolean);

const events = list(payload.events).length ? list(payload.events) : list(appliedResult.events);
const eventLines = events.flatMap(event => {
  const header = text(event.summary);
  const evidence = text(event.evidenceText);
  const effectLines = list(event.effects).map(effect => {
    const code = text(effect.sphereCode);
    const direction = Number(effect.direction);
    const strength = Number(effect.strength);
    const duration = Number(effect.durationDays);
    if (!code || ![-1, 1].includes(direction) || ![1, 2, 3].includes(strength) || ![1, 3, 7, 14].includes(duration)) return '';
    return `${sphereNames[code] || code}: ${direction < 0 ? '−' : '+'}${strength}, ${duration} дн.`;
  }).filter(Boolean);
  return [header, evidence ? `Основание: «${evidence}»` : '', ...effectLines].filter(Boolean);
});

const userScores = list(payload.userScores).length ? list(payload.userScores) : list(appliedResult.userScores);
const scoreLines = userScores.map(score => {
  const code = text(score.sphereCode);
  const value = Number(score.score);
  return code && Number.isFinite(value) ? `${sphereNames[code] || code}: прямая оценка ${value}/10` : '';
}).filter(Boolean);

const identity = object(payload.identityContext);
const displayName = text(payload.displayName || identity.displayName);
const tenantUsername = tenantId.startsWith('tenant_') ? tenantId.slice('tenant_'.length) : '';
const collectionUsername = collection.startsWith('kb_tenant_') ? collection.slice('kb_tenant_'.length) : '';
const storageUsername = text(payload.storageUsername || identity.storageUsername || tenantUsername).replace(/^@+/, '').toLowerCase();
const currentUsername = text(payload.currentUsername || identity.currentUsername || identity.username || '').replace(/^@+/, '').toLowerCase();
const telegramActorId = text(payload.telegramActorId || payload.telegramUserId || identity.telegramActorId || identity.telegramUserId || row.telegramActorId || row.telegram_user_id);
if (!/^tgactor_[a-f0-9]{64}$/.test(principalId) || !/^actor_[a-f0-9]{32}$/.test(storageUsername) || collectionUsername !== storageUsername ||
    tenantId !== `tenant_${storageUsername}` || !/^\d+$/.test(telegramActorId) || Number(telegramActorId)<=0 || (currentUsername && !/^[a-z0-9_]{1,64}$/.test(currentUsername))) {
  throw new Error('State Qdrant outbox: canonical username identity is inconsistent.');
}
const username = currentUsername;
const timezone = text(payload.timezone || identity.timezone || summaryPayload.deliveryContext?.timezone);
const asOfDate = text(payload.asOfDate || payload.localDate || appliedResult.asOfDate || summaryPayload.asOfDate);
const sourceContent = text(payload.content || appliedResult.content);

let pointType;
let knowledgeType;
let title;
let lines;
if (sourceType === 'principal_context') {
  pointType = 'user_state_profile';
  knowledgeType = 'user_state_profile';
  title = `Профиль состояния${displayName ? ` · ${displayName}` : ''}`;
  lines = [
    title,
    `Канонический идентификатор: ${principalId}`,
    displayName ? `Имя: ${displayName}` : '',
    username ? `Текущий username: ${username}` : '',
    timezone ? `Часовой пояс: ${timezone}` : '',
    text(payload.telegramChatId) ? `Telegram chat: ${text(payload.telegramChatId)}` : '',
    text(payload.deliveryAddress) ? `Адрес доставки: ${text(payload.deliveryAddress)}` : '',
    `Версия контекста: ${text(payload.contextVersion || '0')}`
  ];
} else if (sourceType === 'state_summary') {
  pointType = 'user_state_summary';
  knowledgeType = 'user_state_summary';
  title = `Сводка состояния · ${asOfDate || principalId}`;
  const benefit = Number(payload.observedBenefit);
  lines = [
    title,
    stateLines.length ? `Сферы: ${stateLines.join('; ')}` : '',
    Number.isFinite(benefit) ? `Наблюдаемая польза действия: ${benefit}` : '',
    text(payload.evaluationId) ? `Оценка действия: ${text(payload.evaluationId)}` : ''
  ];
} else {
  pointType = 'user_state';
  knowledgeType = sourceType === 'clarification' ? 'user_state_clarification' : 'user_state_observation';
  title = sourceType === 'clarification'
    ? `Уточнение состояния · ${asOfDate || sourceKey}`
    : `Состояние пользователя · ${asOfDate || sourceKey}`;
  lines = [
    title,
    sourceContent ? `Сообщение пользователя: ${sourceContent}` : '',
    ...eventLines,
    ...scoreLines,
    stateLines.length ? `Снимок сфер: ${stateLines.join('; ')}` : '',
    text(payload.targetEffectId) ? `Уточнённый эффект: ${text(payload.targetEffectId)}` : ''
  ];
}

const retrievalText = lines.filter(Boolean).join('\n');
const uploadId = `state:${sourceType}:${sourceKey}`;
const evidenceText = sourceContent || eventLines.join('\n') || stateLines.join('; ') || retrievalText;
const retrievalQuestions = [
  `Как менялось состояние пользователя ${principalId}?`,
  sourceType === 'principal_context' ? `Какой профиль и контекст у пользователя ${principalId}?` : '',
  sourceType === 'state_summary' ? `Какова последняя сводка состояния пользователя ${principalId}?` : '',
  ...stateLines.slice(0, 5).map(line => `Что известно про ${line.split(':')[0]} пользователя?`)
].filter(Boolean);
const tags = [
  'chelsea_state',
  pointType,
  `state_source_${sourceType}`,
  ...events.flatMap(event => list(event.effects).map(effect => `state_${text(effect.sphereCode)}`)).filter(Boolean)
];
const directItem = {
  pointType,
  qdrantPointId: pointId,
  knowledgeId: `${sourceType}:${sourceKey}`,
  knowledgeType,
  type: knowledgeType,
  title,
  summary: eventLines.slice(0, 8).join(' | ') || stateLines.join('; ') || sourceContent || title,
  text: retrievalText,
  retrievalText,
  sourceText: evidenceText,
  evidenceText,
  retrievalQuestions,
  queryAliases: ['состояние пользователя', 'профиль пользователя', ...stateLines.slice(0, 10)],
  tags: [...new Set(tags)],
  tenantId,
  memoryTenantId: tenantId,
  principalId,
  canonicalPrincipalId: principalId,
  sourceType,
  sourceKey,
  stateOutboxId: outboxId,
  sourceMessageId: text(payload.sourceMessageId || appliedResult.sourceMessageId),
  sourceInputId: text(payload.inputId || appliedResult.inputId),
  sourceAnalysisRunId: text(payload.analysisRunId || appliedResult.analysisRunId),
  stateSnapshotId: text(payload.snapshotId || appliedResult.snapshotId || payload.afterSnapshotId),
  stateAsOfDate: asOfDate,
  stateModelVersion: text(payload.calculationVersion || appliedResult.calculationVersion || 'kernel_v0'),
  statePayloadSchemaVersion: text(payload.schemaVersion),
  stateAboutSelf: payload.aboutSelf === true || appliedResult.aboutSelf === true,
  stateAnalysisConfidence: Number(payload.analysisConfidence ?? appliedResult.analysisConfidence ?? 0),
  stateEvents: events,
  stateUserScores: userScores,
  stateEffectMutations: list(payload.effectMutations).length ? list(payload.effectMutations) : list(appliedResult.effectMutations),
  stateValues,
  stateIdentityContext: identity,
  storageUsername,
  currentUsername,
  stateSourcePayload: payload,
  payloadSchemaVersion: 'chelsea_state_qdrant_point_v2',
  payloadShape: 'chelsea_state_qdrant_point_v2',
  sourceTitle: 'Chelsea State',
  uploadId
};

return [{
  json: {
    ...row,
    qdrantDirectMode: true,
    qdrantDirectItems: [directItem],
    qdrantCollection: collection,
    tenantId,
    memoryTenantId: tenantId,
    principalKey: principalId,
    storageUsername,
    currentUsername,
    telegramUsername: currentUsername,
    userId: storageUsername,
    memoryUserId: storageUsername,
    telegramActorId,
    telegramUserId: telegramActorId,
    soulId: `chelsea_soul_${storageUsername}`,
    identitySchemaVersion: 'chelsea_actor_identity_v3',
    identityStatus: text(identity.identityStatus || payload.identityStatus || 'active'),
    principalId,
    universalMemoryMode: false,
    peopleResolutionEnabled: false,
    peopleEntityMode: 'off',
    skipExistingQdrantPoints: true,
    reindexChangedQdrantPoints: true,
    qdrantBatchIndexingEnabled: true,
    qdrantBatchSize: 1,
    sourceTitle: 'Chelsea State',
    sourceText: evidenceText,
    uploadId,
    stateExpectedPointId: pointId
  }
}];

'use strict';
const source=$('Code | Build State Qdrant Load Input | QdrantOutbox').item.json||{};
const summary=$input.first()?.json||{};
const expected=String(source.stateExpectedPointId||'');
const indexedIds=(Array.isArray(summary.indexedExamples)?summary.indexedExamples:[]).map(row=>String(row.id||row.qdrantPointId||''));
const skippedIds=(Array.isArray(summary.skippedExamples)?summary.skippedExamples:[]).map(row=>String(row.id||row.qdrantPointId||''));
const selected=Number(summary.selectedForIndexingCount||0);
const skipped=Number(summary.skippedExistingQdrantPointCount||0);
const checked=Number(summary.checkedQdrantPointCount||0);
const common=summary.status==='done'&&String(summary.qdrantCollection||'')===String(source.qdrantCollection||'')&&checked===1;
const indexed=selected===1&&summary.qdrantReadBackStatus==='verified'&&indexedIds.includes(expected);
const unchanged=selected===0&&skipped===1&&summary.qdrantReadBackStatus==='not_required'&&skippedIds.includes(expected);
const verified=Boolean(common&&(indexed||unchanged));
const receipt={verified,expectedPointId:expected,indexedPointIds:indexedIds,skippedPointIds:skippedIds,status:summary.status||'',qdrantReadBackStatus:summary.qdrantReadBackStatus||'',selectedForIndexingCount:selected,skippedExistingQdrantPointCount:skipped,checkedQdrantPointCount:checked,loaderReturnVersion:summary.loaderReturnVersion||'',completedAt:summary.completedAt||new Date().toISOString()};
return [{json:{...source,stateQdrantReceipt:receipt,stateQdrantVerified:verified,stateQdrantError:verified?'':`loader_receipt_invalid:${JSON.stringify(receipt)}`}}];

'use strict';
const input=$input.first()?.json||{};
let source=input;
try{source=$('Code | Build State Qdrant Load Input | QdrantOutbox').item.json||input;}catch{}
const error=String(input.stateQdrantError||input.error?.message||input.message||'qdrant_loader_failed');
return [{json:{...source,stateRpcBody:{p_outbox_id:source.outbox_id||source.outboxId,p_lease_token:source.lease_token||source.leaseToken,p_expected_outbox_version:Number(source.outbox_version??source.outboxVersion),p_error_code:'qdrant_loader_failed',p_error_text:error.slice(0,2000),p_retry_delay_minutes:1}}}];
